package sdd

import (
	"errors"
	"fmt"
	"regexp"
	"strings"

	protocolcli "go.putnami.dev/protocol/cli"
	diag "go.putnami.dev/protocol/diagnostic"
	wsproto "go.putnami.dev/protocol/workspace"
)

// The agent-attribution gate of `validate-workspace`.
//
// A pull request merges by squash, and the squash commit is the only commit of
// the change that lands on the base branch. A coding agent, or the service that
// hosts it, can sign that message: a "Generated by" footer, a Co-Authored-By
// trailer for a model, a link to the agent's session. Once the commit is on the
// base branch, only a history rewrite removes the signature.
//
// A workspace that forbids such a signature sets options.sdd.agentAttribution
// to "forbid". This gate then reads the proposed squash message from
// PUTNAMI_PROPOSAL_MESSAGE, the variable the breaking-marker gate reads, and
// fails naming each line that signs it. A path such as .claude/ or .agents/,
// and a human co-author, stay allowed.
//
// The verdict reads an environment variable that the candidate cut does not
// hold, so the task is uncached.

// AgentAttributionOption is the key of options.sdd that sets the policy.
const AgentAttributionOption = "agentAttribution"

// The values AgentAttributionOption accepts. Unset reads as allow.
const (
	AgentAttributionAllow  = "allow"
	AgentAttributionForbid = "forbid"
)

// ErrorCodeAgentAttribution is the finding for one line of the squash message
// that names an agent.
const ErrorCodeAgentAttribution = "sdd.agent_attribution"

// ErrorCodeInvalidAgentAttribution is the finding for an option value the
// step does not accept.
const ErrorCodeInvalidAgentAttribution = "sdd.invalid_agent_attribution"

// agentNames lists the coding agents, their hosts and their vendors that a
// signature names. Each is matched as a whole word, case-insensitively.
const agentNames = `claude|anthropic|codex|openai|chatgpt|gpt-[0-9][a-z0-9.-]*|copilot|cursor|gemini|devin|windsurf|aider`

// agentSignatures are the three forms a signature takes, matched line by line.
var agentSignatures = []struct {
	kind    string
	pattern *regexp.Regexp
}{
	// "Generated by" or "Generated with" followed by an agent's name, whatever
	// the markup around it: _Generated by [Name](url)_ reads as one. No \b
	// before "generated": the "_" of italics is a word character.
	{"generated-footer", regexp.MustCompile(`(?i)(?:^|[^a-z0-9])generated\s+(?:by|with)\s+[^a-z0-9\s]*(?:` + agentNames + `)\b`)},
	// A Co-Authored-By trailer whose name or address is an agent's. A human
	// co-author stays allowed.
	{"co-author-trailer", regexp.MustCompile(`(?i)^\s*co-authored-by:.*(?:\b(?:` + agentNames + `)\b|@(?:anthropic|openai)\.com)`)},
	// A link to the agent's session, or the trailer that carries one.
	{"session-link", regexp.MustCompile(`(?i)claude\.ai/code/session_|chatgpt\.com/codex/|^\s*(?:` + agentNames + `)-session:`)},
}

// AgentAttributionReport is the typed data of one agent-attribution judgment.
type AgentAttributionReport struct {
	// Policy is the effective value of options.sdd.agentAttribution.
	Policy string `json:"policy"`
	// Proposal reports whether a proposed squash message was set.
	Proposal bool `json:"proposal"`
	// Note explains a pass that read nothing.
	Note string `json:"note,omitempty"`
	// Subject is the squash commit's subject.
	Subject string `json:"subject,omitempty"`
	// Lines lists every line of the message that names an agent, in order.
	Lines []AgentAttributionLine `json:"lines,omitempty"`
	// Diagnostics carries one finding per such line, or the invalid option.
	Diagnostics []diag.Diagnostic `json:"diagnostics,omitempty"`
}

// AgentAttributionLine is one line of the squash message that names an agent.
type AgentAttributionLine struct {
	// Line is the 1-based line number in the message.
	Line int `json:"line"`
	// Kind is generated-footer, co-author-trailer or session-link.
	Kind string `json:"kind"`
	// Text is the line, trimmed.
	Text string `json:"text"`
}

// BuildAgentAttributionResult reads the proposed squash message for lines that
// name an agent. message is the value of ProposalMessageEnv, and sddOptions the
// workspace's options.sdd block; either may be empty.
func BuildAgentAttributionResult(message string, sddOptions map[string]any) (AgentAttributionReport, error) {
	report := AgentAttributionReport{Policy: AgentAttributionAllow}
	field := wsproto.WorkspaceConfigFilename + "#options.sdd." + AgentAttributionOption
	if raw, set := sddOptions[AgentAttributionOption]; set {
		value, ok := raw.(string)
		if !ok || (value != AgentAttributionAllow && value != AgentAttributionForbid) {
			report.Diagnostics = append(report.Diagnostics, diag.Errorf(ErrorCodeInvalidAgentAttribution, field,
				"must be %q or %q, got %v", AgentAttributionAllow, AgentAttributionForbid, raw))
			return report, WithResultData(protocolcli.Classify(fmt.Errorf(
				"agent attribution: %s must be %q or %q, got %v", field, AgentAttributionAllow, AgentAttributionForbid, raw),
				protocolcli.ErrInvalidConfig), report)
		}
		report.Policy = value
	}
	if report.Policy != AgentAttributionForbid {
		report.Note = "the workspace allows agent attribution: set options.sdd." + AgentAttributionOption + " to \"forbid\" to check the squash message"
		return report, nil
	}
	if strings.TrimSpace(message) == "" {
		report.Note = "no proposal message to read: " + ProposalMessageEnv + " is unset or blank"
		return report, nil
	}
	report.Proposal = true
	report.Subject, _ = splitCommitMessage(message)

	for i, line := range strings.Split(strings.ReplaceAll(message, "\r\n", "\n"), "\n") {
		for _, signature := range agentSignatures {
			if signature.pattern.MatchString(line) {
				report.Lines = append(report.Lines, AgentAttributionLine{Line: i + 1, Kind: signature.kind, Text: strings.TrimSpace(line)})
				break
			}
		}
	}
	if len(report.Lines) == 0 {
		return report, nil
	}

	var failure strings.Builder
	fmt.Fprintf(&failure, "agent attribution: the squash commit %q names an agent on %d line(s):\n", report.Subject, len(report.Lines))
	for _, line := range report.Lines {
		fmt.Fprintf(&failure, "  line %d (%s): %s\n", line.Line, line.Kind, line.Text)
		report.Diagnostics = append(report.Diagnostics, diag.Errorf(ErrorCodeAgentAttribution, "",
			"line %d of the squash commit %q names an agent (%s): %s", line.Line, report.Subject, line.Kind, line.Text))
	}
	failure.WriteString("Remove each line from the title or the body: the workspace sets options.sdd." + AgentAttributionOption +
		" to \"forbid\". A path such as .claude/ and a human co-author stay allowed.")
	return report, WithResultData(protocolcli.Classify(errors.New(failure.String()), protocolcli.ErrInvalidConfig), report)
}
